 private static void waitRefresh(Instrumentation runner,MainActivity a)throws Exception{
  long until=SystemClock.uptimeMillis()+8000;boolean[] busy={true};while(SystemClock.uptimeMillis()<until){main(runner,()->busy[0]=(boolean)get(a,"busy"));if(!busy[0]){runner.waitForIdleSync();return;}SystemClock.sleep(20);}throw new AssertionError("Refresh did not finish");
 }
